```python
from fractions import Fraction
import json

result = Fraction(144, 12)
if result.denominator != 1:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": str(result.numerator),
        "evidence": "144/12 = 12"
    }))
```

